def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    my_last, opp_last = history[-1]

    # Early game: simple Tit-for-Tat to establish cooperation or punish immediate defection
    if n < 10:
        return 'C' if opp_last == 'C' else 'D'

    # Calculate statistics
    opp_defections = sum(1 for a, b in history if b == 'D')
    opp_coop_rate = (n - opp_defections) / n

    recent_window = min(n, 20)
    recent = history[-recent_window:]
    recent_opp_coop = sum(1 for a, b in recent if b == 'C') / recent_window
    recent_opp_defects = recent_window - sum(1 for a, b in recent if b == 'C')

    # Detect Pure Defectors early and punish hard
    if opp_coop_rate < 0.1 and n > 15:
        return 'D'

    # Detect Very Cooperative Opponents
    if opp_coop_rate > 0.9 and recent_opp_coop > 0.8:
        # Exploit slightly in the endgame if they are passive, but keep them happy mostly
        if n >= 90:
            return 'D'
        # Occasionally defect to test, but rarely to avoid breaking CC loop
        if rng.random() < 0.02:
            return 'D'
        return 'C'

    # Mid-game logic based on recent behavior
    if n < 30:
        if opp_coop_rate > 0.7:
            return 'C'
        if opp_coop_rate < 0.3:
            return 'D'
        return 'C' if opp_last == 'C' else 'D'

    # General Strategy
    if recent_opp_coop < 0.25:
        return 'D'

    if opp_last == 'D':
        # Check if this is a single slip-up by a generally cooperative player
        if recent_opp_coop > 0.6:
            # High chance of forgiving if opponent is mostly good
            if rng.random() < 0.7:
                return 'C'
            return 'D'

        # Otherwise, retaliate strongly
        recent_defections = sum(1 for a, b in history[-5:] if b == 'D')
        if recent_defections >= 2:
            return 'D'

        # In late game, punish more severely
        if n >= 85:
            return 'D'

        return 'D' if rng.random() < 0.8 else 'C'

    # Opponent cooperated last round
    if recent_opp_coop < 0.5:
        # Mixed strategy against unpredictable/opportunistic players
        return 'D' if rng.random() < 0.4 else 'C'

    if n >= 95:
        # Endgame: Defect unless they have been perfectly cooperative recently
        if recent_opp_coop > 0.95:
            return 'C'
        return 'D'

    return 'C'
